function containsExactCharacterQty(bytes32 source, uint8 utf8CharCode, uint8 targetQty)
        internal
        pure
        returns (bool)
    {
        uint8 _occurrences = 0;
        for (uint8 i = 0; i < 32;) {
            uint8 _charCode = uint8(source[i]);
            // if not a null byte, or a multi-byte UTF-8 character, check match
            if (_charCode != 0 && _charCode < 0x80) {
                if (_charCode == utf8CharCode) {
                    unchecked {
                        // no risk of overflow since max 32 iterations < max uin8=255
                        ++_occurrences;
                    }
                }
            }
            unchecked {
                // no risk of overflow since max 32 iterations < max uin8=255
                ++i;
            }
        }
        return _occurrences == targetQty;
    }

function toString(bytes32 source) internal pure returns (string memory result) {
        uint8 length;
        while (source[length] != 0 && length < 32) {
            length++;
        }
        assembly {
            // free memory pointer
            result := mload(0x40)
            // update free memory pointer to new "memory end"
            // (offset is 64-bytes: 32 for length, 32 for data)
            mstore(0x40, add(result, 0x40))
            // store length in first 32-byte memory slot
            mstore(result, length)
            // write actual data in second 32-byte memory slot
            mstore(add(result, 0x20), source)
        }
    }

function read(address pointer) internal view returns (bytes memory data) {
        uint256 codeSize = pointer.code.length;
        if (codeSize < DATA_OFFSET) {
            revert SSTORE2InvalidPointer(pointer);
        }
        bytes1 prefix;
        assembly ("memory-safe") {
            extcodecopy(pointer, 0x00, 0x00, 0x01)
            prefix := mload(0x00)
        }
        if (prefix != bytes1(0)) {
            revert SSTORE2InvalidPointer(pointer);
        }
        uint256 size;
        unchecked {
            size = codeSize - DATA_OFFSET;
        }
        data = new bytes(size);
        assembly ("memory-safe") {
            extcodecopy(pointer, add(data, 0x20), DATA_OFFSET, size)
        }
    }

